RUQL_ITEMS[43627]={"Золотая монета Тралла","Покойся в мире, Гром, старый друг…"}
RUQL_ITEMS[43628]={"Золотая монета леди Джайны Праудмур","Артас, любовь моя, пожалуйста, вернись!"}
RUQL_ITEMS[43629]={"Золотая монета Утера Светоносного","Юному Артасу следует научиться терпению. Одного могущества мало… Я буду молиться, чтобы он со временем научился действовать без применени"}
RUQL_ITEMS[43630]={"Золотая монета Тириона Фордринга","Хочу, чтобы мой Таэлан вырос достаточно сильным, чтобы защищать тех, кто ему небезразличен!"}
RUQL_ITEMS[43631]={"Золотая монета Терона","Желания – забава для глупцов. Прими эту монету как плату за свое драгоценное Око."}
RUQL_ITEMS[43632]={"Золотая монета Сильваны Ветрокрылой","Надеюсь, мы с сестрами вырастем и вместе выйдем замуж… Эта монета кажется очень древней."}
RUQL_ITEMS[43633]={"Золотая монета принца Кель'таса Солнечного Скитальца","Эта юная волшебница, Джайна, довольно привлекательна для человеческой девушки. Надеюсь, она уже заметила, как я силен и импозантен."}
RUQL_ITEMS[43634]={"Золотая монета леди Катраны Престор","Слушай, ты, фонтанишко для желаний! Быстро отдай мне всю свою силу, а не то тебе не поздоровится!"}
RUQL_ITEMS[43635]={"Золотая монета Кел'Тузада","Иногда… иногда мне хочется, чтобы кто-нибудь просто подошел ко мне и крепко-крепко обнял."}
RUQL_ITEMS[43636]={"Золотая монета Хроми","Я желаю, чтобы кто-нибудь хоть раз обратился ко мне нормально, не отпустив идиотскую шуточку про гномов и путешествия во времени..."}
RUQL_ITEMS[43637]={"Золотая монета Бранна Бронзоборода","Здесь был Бранн Бронзобород."}
RUQL_ITEMS[43638]={"Золотая монета Аругала","Вот мое желание: удалиться на покой в маленький, уютный домик, и чтобы сопровождали меня только верные собаки."}
RUQL_ITEMS[43639]={"Золотая монета Артаса","Итак, у меня есть королевство и земли. Чего еще желать? Ледяной трон?"}
RUQL_ITEMS[43640]={"Золотая монета Архимонда","Хотел бы я знать, как ты избежал моего гнева, фонтанишко."}
RUQL_ITEMS[43641]={"Золотая монета Андуина Ринна","Я хочу скорее вырасти! Кажется, я просто застрял на десятилетнем возрасте!"}
RUQL_ITEMS[43643]={"Серебряная монета принца Магни Бронзоборода","Надеюсь, отец и братья переживут меня. Ну какой из меня король?"}
RUQL_ITEMS[43644]={"Серебряная монета крестьянина","Экий я забывчивый! Совсем памяти не стало… Постой-ка, я же, вроде, уже бросил туда одну монету?"}
RUQL_ITEMS[43645]={"Погнутый рыболовный крючок","Похоже, кто-то пытался ловить рыбу в этом фонтане. Интересно, кому пришла в голову такая дурацкая мысль?"}
RUQL_ITEMS[43646]={"Золотая рыбка из фонтана",nil}
